WITH base AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, firmware, DATEDIFF(CURRENT_DATE(), reading_ts) / 365 AS years_since_reading_ts, WEEKOFYEAR(reading_ts) AS reading_ts_weekofyear FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 08:00:00'), cleaned AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, firmware, years_since_reading_ts, LENGTH(device_code) AS device_code_length, CASE WHEN firmware = '1.0.3' THEN 1 ELSE 0 END AS is_1_0_3 FROM base WHERE reading_ts > DATE '2025-09-01' AND pressure <= 999), kept_keys AS (SELECT firmware, device_code FROM cleaned EXCEPT ALL SELECT firmware, device_code FROM device_readings WHERE temp_c BETWEEN 29 AND 38), verified AS (SELECT s.* FROM cleaned s INNER JOIN kept_keys k ON s.firmware = k.firmware AND s.device_code = k.device_code), filtered AS (SELECT id, device_code, reading_ts, humidity, pressure, firmware, years_since_reading_ts, humidity - device_code_length AS humidity_minus_device_code_length FROM verified WHERE reading_ts > TO_DATE('2025-09-01')) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, DATE_TRUNC('HOUR', reading_ts) AS hour_window, AVG(humidity_minus_device_code_length) FILTER (WHERE device_code = 'DV-04') AS dv_04_avg_humidity_minus_device_code_length, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, COUNT_IF(device_code = 'DV-03') AS dv_03_events, RANK() OVER (PARTITION BY DATE_TRUNC('DAY', reading_ts) ORDER BY COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) DESC) AS dv_01_count_rank FROM filtered GROUP BY DATE_TRUNC('DAY', reading_ts), DATE_TRUNC('HOUR', reading_ts) ORDER BY dv_01_count DESC NULLS LAST
